package com.sathavahana.kalamkari.service;
import com.sathavahana.kalamkari.domain.*; import com.sathavahana.kalamkari.dto.OrderDto; import com.sathavahana.kalamkari.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*;
@Service public class OrderService {private final OrderRepository orders; private final CartRepository carts; private final CurrentUser current; public OrderService(OrderRepository o,CartRepository c,CurrentUser u){orders=o;carts=c;current=u;} @Transactional public OrderDto checkout(){var u=current.require(); var c=carts.findByUserId(u.getId()).orElseThrow(()->new IllegalArgumentException("Cart is empty")); if(c.getItems().isEmpty())throw new IllegalArgumentException("Cart is empty"); var o=new Order(u); var total=BigDecimal.ZERO; for(var item:c.getItems()){var oi=new OrderItem(o,item.getProduct(),item.getQuantity());o.getItems().add(oi); total=total.add(item.getUnitPrice().multiply(BigDecimal.valueOf(item.getQuantity())));}o.setTotalAmount(total); return OrderDto.of(orders.save(o));} @Transactional(readOnly=true) public java.util.List<OrderDto> list(){return orders.findByUserIdOrderByCreatedAtDesc(current.require().getId()).stream().map(OrderDto::of).toList();}}
